import { PrismaPg } from '@prisma/adapter-pg';
import { env } from '../config/env.js';
// Generated by `prisma generate` from prisma/schema.prisma (TypeScript, run natively by Node).
import { PrismaClient } from '../generated/prisma/client.ts';

/**
 * Single shared Prisma Client for the whole app.
 * Prisma 7 talks to PostgreSQL through a driver adapter (node-postgres here).
 */
export const prisma = new PrismaClient({
  adapter: new PrismaPg({ connectionString: env.DATABASE_URL }),
  log: env.isProduction ? ['error'] : ['warn', 'error'],
});
